CREATE OR REPLACE FUNCTION app_private.applicant_profile_missing_fields(p_user uuid)
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  p public.applicant_profiles%rowtype;
  v_missing text[] := array[]::text[];
begin
  select * into p
  from public.applicant_profiles
  where user_id=p_user;

  if not found then
    return array['Vorname','Nachname','E-Mail-Adresse'];
  end if;

  if nullif(trim(coalesce(p.first_name,'')),'') is null then
    v_missing := array_append(v_missing,'Vorname');
  end if;
  if nullif(trim(coalesce(p.last_name,'')),'') is null then
    v_missing := array_append(v_missing,'Nachname');
  end if;
  if p.email is null or lower(trim(p.email)) !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' then
    v_missing := array_append(v_missing,'E-Mail-Adresse');
  end if;
  return v_missing;
end
$function$

CREATE OR REPLACE FUNCTION app_private.application_target_ready(p_user uuid, p_source_id smallint, p_raw jsonb, p_canonical_url text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare v_provider text;
begin
 v_provider:=app_private.application_provider_target(p_source_id,p_raw,p_canonical_url);
 if v_provider is null or not exists(select 1 from public.platform_connections c where c.user_id=p_user and c.provider=v_provider and c.status='connected') then return false; end if;
 if v_provider='immomio' then return true; end if;
 return exists(select 1 from app_private.application_platforms p where p.source_id=p_source_id and p.verified_at is not null);
end $function$

CREATE OR REPLACE FUNCTION app_private.apply_property_classification()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  c jsonb;
begin
  if tg_op='UPDATE' and old.raw?'category_stream' and not new.raw?'category_stream' then
    new.raw:=coalesce(new.raw,'{}'::jsonb)||jsonb_build_object(
      'category_stream',old.raw->'category_stream',
      '_newness',old.raw->'_newness'
    );
    new.fresh_delivery_eligible:=old.fresh_delivery_eligible;
  end if;

  c:=app_private.classify_listing_category(
    new.source_id,new.property_type,new.property_kind,new.offer_mode,new.title,new.raw
  );

  new.property_kind:=coalesce(c->>'kind','unknown');
  new.offer_mode:=coalesce(c->>'mode','unknown');
  new.property_type:=c->>'category';
  new.raw:=coalesce(new.raw,'{}'::jsonb)||jsonb_build_object('_classification',c);

  if new.offer_mode in ('sale','wanted') then
    new.is_active:=false;
    new.quality_status:='rejected';
    new.quality_reason:='not_a_residential_rental_offer';
  elsif new.quality_reason='not_a_residential_rental_offer' then
    new.quality_status:='unchecked';
    new.quality_reason:=null;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.apply_source_specific_field_repairs()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_rooms numeric; v_warm numeric; v_cold numeric; m text[];
begin
  if new.enrichment_status<>'done' then return new; end if;
  m:=regexp_match(coalesce(new.title,''),'(?i)([0-9]+(?:[.,][0-9]+)?)\s*[-– ]\s*Zimmer');
  if m is not null then begin v_rooms:=replace(m[1],',','.')::numeric; exception when others then v_rooms:=null; end; end if;

  if new.source_id=2 then
    if new.cold_rent is null and new.enrichment_evidence->'cold_rent'->>'source'='detail:text' then v_cold:=(new.enrichment_evidence->'cold_rent'->>'value')::numeric; end if;
    if new.warm_rent is null and new.enrichment_evidence->'warm_rent'->>'source'='detail:text' then v_warm:=(new.enrichment_evidence->'warm_rent'->>'value')::numeric; end if;
  elsif new.source_id=9 then
    if v_rooms is null and new.enrichment_evidence->'rooms'->>'source' like 'raw:jsonld.%' and coalesce((new.enrichment_evidence->'rooms'->>'confidence')::numeric,0)>=0.95 then v_rooms:=(new.enrichment_evidence->'rooms'->>'value')::numeric; end if;
    if new.warm_rent is null then v_warm:=nullif(replace(substring(coalesce(new.title,'') from '€[[:space:]]*([0-9]+[,.]?[0-9]*)[[:space:]]*/month,[[:space:]]*incl'),',','.'),'')::numeric; end if;
    if new.deposit is null and lower(coalesce(new.title,'')) like '%no deposit%' then new.deposit:=0; new.enrichment_evidence:=jsonb_set(coalesce(new.enrichment_evidence,'{}'::jsonb),'{deposit}',jsonb_build_object('value',0,'source','pre_delivery:title_no_deposit','confidence',0.99),true); end if;
  elsif new.source_id=12 and v_rooms is null then
    v_rooms:=nullif(replace(substring(coalesce(new.title,'') from ' ([0-9]+[,.]?[0-9]*) [0-9]+[,.]?[0-9]*m² Monatsrate'),',','.'),'')::numeric;
  elsif new.source_id=15 and v_rooms is null then
    v_rooms:=nullif(replace(substring(coalesce(new.title,'') from 'Zimmer ([0-9]+[,.]?[0-9]*) Etage'),',','.'),'')::numeric;
  elsif new.source_id=6 and v_rooms is null then
    v_rooms:=nullif(replace(coalesce(substring(coalesce(new.title,'') from '([0-9]+[,.]?[0-9]*)[ -]+Zimmer'),substring(coalesce(new.title,'') from '^([0-9]+[,.]?[0-9]*)[^0-9]{0,15}Zi')),',','.'),'')::numeric;
  end if;

  if v_rooms is not null and v_rooms between 0.5 and 50 then new.rooms:=v_rooms; new.enrichment_evidence:=jsonb_set(coalesce(new.enrichment_evidence,'{}'::jsonb),'{rooms}',jsonb_build_object('value',v_rooms,'source','pre_delivery:source_specific','confidence',0.99),true); new.field_conflicts:=coalesce(new.field_conflicts,'{}'::jsonb)-'rooms'; end if;
  if v_cold is not null and v_cold between 1 and 100000 and new.cold_rent is null then new.cold_rent:=v_cold; end if;
  if v_warm is not null and v_warm between 1 and 100000 and new.warm_rent is null then new.warm_rent:=v_warm; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.assert_platform_connect_context(p_flow platform_auth_flows)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_issuer public.coaching_members%rowtype;
begin
  perform 1 from public.bot_users where id=p_flow.user_id and is_active for share;
  if not found then raise exception 'auth_flow_expired'; end if;
  if p_flow.provider<>'wg_gesucht' and not exists(select 1 from public.coach_effective_premium_status(array[p_flow.user_id]) where is_premium)
  then raise exception 'premium_required'; end if;
  if p_flow.origin='coach' then
    select * into v_issuer from public.coaching_members where auth_user_id=p_flow.issued_by and is_active for share;
    if not found then raise exception 'auth_flow_expired'; end if;
    perform 1 from public.coaching_workspaces where id=v_issuer.workspace_id and is_active and not operations_paused for share;
    if not found then raise exception 'auth_flow_expired'; end if;
    perform 1 from public.coaching_participants where user_id=p_flow.user_id and workspace_id=v_issuer.workspace_id and status='active'
      and assignment_version::text=p_flow.context->>'assignment_version' and (v_issuer.role='admin' or coach_member_id=v_issuer.id) for share;
    if not found then raise exception 'auth_flow_expired'; end if;
  elsif p_flow.origin='telegram' then
    if not exists(select 1 from public.bot_users where id=p_flow.user_id and telegram_user_id is not null and chat_id is not null)
    then raise exception 'auth_flow_expired'; end if;
  end if;
end $function$

CREATE OR REPLACE FUNCTION app_private.capture_listing_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  f text[] := '{}';
  ov jsonb := '{}';
  nv jsonb := '{}';
begin
  if old.warm_rent is distinct from new.warm_rent then
    f := array_append(f, 'warm_rent');
    ov := ov || jsonb_build_object('warm_rent', old.warm_rent);
    nv := nv || jsonb_build_object('warm_rent', new.warm_rent);
  end if;
  if old.cold_rent is distinct from new.cold_rent then
    f := array_append(f, 'cold_rent');
    ov := ov || jsonb_build_object('cold_rent', old.cold_rent);
    nv := nv || jsonb_build_object('cold_rent', new.cold_rent);
  end if;
  if old.deposit is distinct from new.deposit then
    f := array_append(f, 'deposit');
    ov := ov || jsonb_build_object('deposit', old.deposit);
    nv := nv || jsonb_build_object('deposit', new.deposit);
  end if;
  if old.rooms is distinct from new.rooms then
    f := array_append(f, 'rooms');
    ov := ov || jsonb_build_object('rooms', old.rooms);
    nv := nv || jsonb_build_object('rooms', new.rooms);
  end if;
  if old.area_sqm is distinct from new.area_sqm then
    f := array_append(f, 'area_sqm');
    ov := ov || jsonb_build_object('area_sqm', old.area_sqm);
    nv := nv || jsonb_build_object('area_sqm', new.area_sqm);
  end if;
  if old.available_from is distinct from new.available_from then
    f := array_append(f, 'available_from');
    ov := ov || jsonb_build_object('available_from', old.available_from);
    nv := nv || jsonb_build_object('available_from', new.available_from);
  end if;
  if old.canonical_url is distinct from new.canonical_url then
    f := array_append(f, 'canonical_url');
    ov := ov || jsonb_build_object('canonical_url', old.canonical_url);
    nv := nv || jsonb_build_object('canonical_url', new.canonical_url);
  end if;
  if old.is_active is distinct from new.is_active then
    f := array_append(f, 'is_active');
    ov := ov || jsonb_build_object('is_active', old.is_active);
    nv := nv || jsonb_build_object('is_active', new.is_active);
  end if;
  if cardinality(f) > 0 then
    insert into public.listing_changes(listing_id, changed_fields, old_values, new_values)
    values(new.id, f, ov, nv);
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.capture_performance_snapshot()
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  bucket timestamptz := date_bin(interval '4 hours',now(),timestamptz '2000-01-01');
  inserted integer;
begin
  if exists (select 1 from app_private.performance_snapshots where bucket_start=bucket) then
    return false;
  end if;
  insert into app_private.performance_snapshots(bucket_start,captured_at,metrics)
  select bucket,now(),jsonb_build_object(
    'schema_version',1,
    'postmaster_start',pg_postmaster_start_time(),
    'database_bytes',pg_database_size(current_database()),
    'database',(select to_jsonb(d) from pg_stat_database d where datname=current_database()),
    'wal',(select to_jsonb(w) from pg_stat_wal w),
    'tables',(select jsonb_agg(jsonb_build_object(
      'schema',schemaname,'table',relname,
      'bytes',pg_total_relation_size(relid),
      'index_bytes',pg_indexes_size(relid),
      'live_estimate',n_live_tup,'dead_estimate',n_dead_tup,
      'inserts',n_tup_ins,'updates',n_tup_upd,'hot_updates',n_tup_hot_upd,
      'deletes',n_tup_del,'seq_scans',seq_scan,'index_scans',idx_scan
    ) order by schemaname,relname) from pg_stat_user_tables
       where schemaname in ('public','app_private','pgmq','cron')),
    'sources',(select jsonb_agg(jsonb_build_object(
      'id',id,'name',name,'enabled',enabled,'runtime_mode',runtime_mode,
      'since',telemetry_since,'crawls',telemetry_crawls,'errors',telemetry_errors,
      'candidates',telemetry_candidates,'new_rows',telemetry_new_rows,
      'elapsed_ms',telemetry_elapsed_ms,'consecutive_failures',consecutive_failures
    ) order by id) from public.sources)
  ) on conflict (bucket_start) do nothing;
  get diagnostics inserted=row_count;
  delete from app_private.performance_snapshots where captured_at<now()-interval '35 days';
  return inserted=1;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.classify_listing_category(p_source_id bigint, p_property_type text, p_property_kind text, p_offer_mode text, p_title text, p_raw jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_caps jsonb := '{}'::jsonb;
  v_c jsonb := coalesce(p_raw,'{}'::jsonb)->'_classification';
  v_text text := lower(concat_ws(' ',
    coalesce(p_title,''),
    coalesce(p_raw->>'text',''),
    coalesce(p_raw->>'alt',''),
    coalesce(p_raw->>'query',''),
    coalesce(p_raw#>>'{entry,title}','')
  ));
  v_provider text := lower(coalesce(p_raw->>'provider',''));
  v_stream text := lower(coalesce(p_raw->>'category_stream',''));
  v_kind text := null;
  v_mode text := null;
  v_category text := null;
  v_kind_evidence text := null;
  v_mode_evidence text := null;
  v_kinds jsonb := '[]'::jsonb;
  v_modes jsonb := '[]'::jsonb;
begin
  select coalesce(search_capabilities,'{}'::jsonb)
    into v_caps
  from public.sources
  where id=p_source_id;

  v_kinds:=coalesce(v_caps->'configured_kinds','[]'::jsonb);
  v_modes:=coalesce(v_caps->'offer_modes','[]'::jsonb);

  if coalesce(v_c->>'version','')='4'
     and v_c->>'kind' in ('apartment','house','room')
     and v_c->>'mode' in ('rent','swap','sale','wanted') then
    v_kind:=v_c->>'kind';
    v_mode:=v_c->>'mode';
    v_kind_evidence:='source_classification';
    v_mode_evidence:='source_classification';
  else
    if coalesce(p_offer_mode,'') in ('sale','wanted') then
      v_mode:=p_offer_mode;
      v_mode_evidence:='stored_mode';
    elsif v_text ~ '(^|[[:space:]])(ich|wir)[[:space:]]+suche(n)?[[:space:]].{0,50}(wohnung|apartment|wg[[:space:]-]*zimmer|zimmer|haus)'
       or v_text ~ '(^|[[:space:]])(wohnung|apartment|wg[[:space:]-]*zimmer|zimmer|haus)[[:space:]]+gesucht([[:space:]]|$)'
       or v_text ~ '^[[:space:]]*suche[[:space:]]+(eine[nrsm]?[[:space:]]+|nach[[:space:]]+)?(wohnung|apartment|wg[[:space:]-]*zimmer|zimmer|haus)([[:space:]]|$)' then
      v_mode:='wanted'; v_mode_evidence:='text_wanted';
    elsif v_text ~ '(^|[[:space:]])(zum[[:space:]]+kauf|kaufpreis|zu[[:space:]]+verkaufen|verkauf|mietkauf|erbpacht)([[:space:]]|$)' then
      v_mode:='sale'; v_mode_evidence:='text_sale';
    elsif p_property_type='Tauschwohnung'
       or p_offer_mode='swap'
       or (
         v_text ~ '(tauschwohnung|tauschangebot|wohnungstausch|wohnung[[:space:]-]*tausch|(^|[[:space:]])tausche([[:space:]]|$)|(^|[[:space:]])tauschen([[:space:]]|$)|nur[[:space:]]+tauschen)'
         and v_text !~ '(kein(e|en)?|ohne)[[:space:]]+(tauschwohnung|wohnungstausch|tausch)'
       ) then
      v_mode:='swap';
      v_mode_evidence:=case when p_property_type='Tauschwohnung' then 'stored_category' when p_offer_mode='swap' then 'stored_mode' else 'text_swap' end;
    elsif p_offer_mode='rent' then
      v_mode:='rent'; v_mode_evidence:='stored_mode';
    elsif jsonb_array_length(v_modes)=1 and v_modes->>0 in ('rent','swap') then
      v_mode:=v_modes->>0; v_mode_evidence:='source_scope';
    elsif upper(coalesce(p_raw#>>'{entry,price,marketingType}',''))='RENT'
       or v_text ~ '(^|[[:space:]])(zur[[:space:]]+miete|vermietung|vermiete|mieten|untermiete|zwischenmiete)([[:space:]]|$)' then
      v_mode:='rent'; v_mode_evidence:='text_rent';
    else
      v_mode:='unknown'; v_mode_evidence:='insufficient';
    end if;

    if coalesce(p_property_kind,'') in ('apartment','house','room') then
      v_kind:=p_property_kind; v_kind_evidence:='stored_kind';
    elsif v_stream='room' then
      v_kind:='room'; v_kind_evidence:='room_stream';
    elsif v_stream='house' then
      v_kind:='house'; v_kind_evidence:='house_stream';
    elsif v_text ~ '(wg[[:space:]-]*zimmer|zimmer[[:space:]]+in[[:space:]]+(einer[[:space:]]+)?wg|zimmer.{0,60}[0-9]+er.{0,24}wg|privatzimmer|untermietzimmer|mitbewohner(in)?([[:space:]]|$)|zimmer.{0,40}gemeinschafts(küche|bad))' then
      v_kind:='room'; v_kind_evidence:='text_room';
    elsif v_text ~ '(^|[^[:alnum:]])(einfamilienhaus|reihenhaus|doppelhaus|doppelhaushälfte|bungalow|villa|stadthaus|haus[[:space:]]+zur[[:space:]]+miete|haus[[:space:]]+mieten)([^[:alnum:]]|$)' then
      v_kind:='house'; v_kind_evidence:='text_house';
    elsif v_text ~ '(wohnung|whg([^[:alnum:]]|$)|zi[.]?[[:space:]-]*whg([^[:alnum:]]|$)|zimmerwohnung|apartment|appartment|penthouse|maisonette|loft|studio|etagenwohnung|terrassenwohnung|dachgeschosswohnung|erdgeschosswohnung)' then
      v_kind:='apartment'; v_kind_evidence:='text_apartment';
    elsif p_property_type in ('Wohnung','Haus','WG') then
      v_kind:=case p_property_type when 'Wohnung' then 'apartment' when 'Haus' then 'house' else 'room' end;
      v_kind_evidence:='stored_category';
    elsif p_property_type='Tauschwohnung' then
      if jsonb_array_length(v_kinds)=1 and v_kinds->>0 in ('apartment','house','room') then
        v_kind:=v_kinds->>0; v_kind_evidence:='source_scope';
      else
        v_kind:='apartment'; v_kind_evidence:='stored_category';
      end if;
    elsif jsonb_array_length(v_kinds)=1 and v_kinds->>0 in ('apartment','house','room') then
      v_kind:=v_kinds->>0; v_kind_evidence:='source_scope';
    elsif v_provider='kleinanzeigen'
       and coalesce((p_raw->>'native_offer')::boolean,false)
       and v_stream='' then
      v_kind:='apartment'; v_kind_evidence:='provider_default_apartment';
    elsif v_provider='wunderflats_catalog' then
      v_kind:='apartment'; v_kind_evidence:='provider_default_apartment';
    elsif v_mode='swap' then
      v_kind:='apartment'; v_kind_evidence:='swap_default';
    else
      v_kind:='unknown'; v_kind_evidence:='insufficient';
    end if;
  end if;

  -- Product rule: explicit "Wohnen auf Zeit" belongs to WG, even if a portal
  -- technically models the unit as an apartment.
  if v_mode='rent'
     and v_text ~ '(wohnen[[:space:]-]+auf[[:space:]-]+zeit|zeitwohnen|temporary[[:space:]-]+rent)' then
    v_kind:='room';
    v_kind_evidence:='temporary_housing_to_wg';
  end if;

  v_category:=case
    when v_mode='swap' and v_kind in ('apartment','house','room') then 'Tauschwohnung'
    when v_mode='rent' and v_kind='apartment' then 'Wohnung'
    when v_mode='rent' and v_kind='house' then 'Haus'
    when v_mode='rent' and v_kind='room' then 'WG'
    else null
  end;

  return jsonb_build_object(
    'version',4,
    'kind',coalesce(v_kind,'unknown'),
    'mode',coalesce(v_mode,'unknown'),
    'category',v_category,
    'kind_evidence',coalesce(v_kind_evidence,'insufficient'),
    'mode_evidence',coalesce(v_mode_evidence,'insufficient')
  );
end
$function$

CREATE OR REPLACE FUNCTION app_private.delivery_newness_qualified(p_listing_id uuid, p_as_of timestamp with time zone DEFAULT now())
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  l public.listings%rowtype;
  c app_private.source_category_streams%rowtype;
  published timestamptz;
  proof jsonb;
begin
  select * into l from public.listings where id=p_listing_id;
  if not found then return false; end if;

  if l.source_id=1 and coalesce(l.raw->>'delivery_lane','')='map_delta' then
    if not coalesce(l.fresh_delivery_eligible,false)
       or l.first_seen_at is null
       or l.first_seen_at < p_as_of-interval '24 hours'
       or l.first_seen_at > p_as_of+interval '5 minutes'
    then return false; end if;
    proof:=l.raw->'_newness';
    if proof->>'method'<>'map_snapshot_delta' or proof->>'observed_at' is null then return false; end if;
    begin published:=(proof->>'observed_at')::timestamptz;
    exception when others then return false; end;
    return published>=p_as_of-interval '24 hours'
       and published<=p_as_of+interval '5 minutes'
       and l.first_seen_at>=published-interval '5 minutes';
  end if;

  if l.raw ? 'category_stream' then
    select * into c
    from app_private.source_category_streams
    where source_id=l.source_id and category=l.raw->>'category_stream';

    if not found
       or not c.enabled
       or c.verified_at is null
       or c.baseline_at is null
       or not coalesce(l.fresh_delivery_eligible,false)
       or l.first_seen_at<c.baseline_at
       or l.first_seen_at<p_as_of-interval '24 hours'
       or l.first_seen_at>p_as_of+interval '5 minutes'
    then return false; end if;

    proof:=l.raw->'_newness';
    if proof->>'method'='source_timestamp' then
      begin published:=(proof->>'source_published_at')::timestamptz;
      exception when others then return false; end;
    elsif proof->>'method'='complete_snapshot_delta' and proof->>'previous_complete_at' is not null then
      begin published:=(proof->>'previous_complete_at')::timestamptz;
      exception when others then return false; end;
      if published<c.baseline_at or l.first_seen_at<published then return false; end if;
    elsif proof->>'method'='poll_delta' and proof->>'previous_success_at' is not null then
      begin published:=(proof->>'previous_success_at')::timestamptz;
      exception when others then return false; end;
      if published<c.baseline_at or l.first_seen_at<published then return false; end if;
    else return false;
    end if;

    return coalesce(published>=p_as_of-interval '24 hours' and published<=p_as_of+interval '5 minutes',false);
  end if;

  return app_private.delivery_newness_qualified_legacy(p_listing_id,p_as_of);
end
$function$

CREATE OR REPLACE FUNCTION app_private.delivery_newness_qualified_legacy(p_listing_id uuid, p_as_of timestamp with time zone DEFAULT now())
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v record;
  v_label text;
  v_local timestamp;
  v_match text[];
  v_day date;
  v_pub timestamptz;
begin
  select
    l.source_id,
    l.first_seen_at,
    l.fresh_delivery_eligible,
    l.raw,
    l.enrichment_evidence,
    s.baseline_completed_at
  into v
  from public.listings l
  join public.sources s on s.id=l.source_id
  where l.id=p_listing_id;

  if not found then return false; end if;

  if v.baseline_completed_at is null
     or v.first_seen_at is null
     or v.first_seen_at < p_as_of - interval '24 hours'
     or v.first_seen_at > p_as_of + interval '5 minutes'
  then
    return false;
  end if;

  if v.source_id=2 then
    if coalesce(v.raw->>'lane','') <> 'fast'
       or not coalesce(v.fresh_delivery_eligible,false)
    then
      return false;
    end if;

    v_label := btrim(coalesce(v.raw->>'sorting_date',''));
    v_local := p_as_of at time zone 'Europe/Berlin';

    v_match := regexp_match(v_label,'^Heute,[[:space:]]*([0-9]{1,2}):([0-9]{2})$','i');
    if v_match is not null then
      v_day := v_local::date;
    else
      v_match := regexp_match(v_label,'^Gestern,[[:space:]]*([0-9]{1,2}):([0-9]{2})$','i');
      if v_match is null then return false; end if;
      v_day := v_local::date - 1;
    end if;

    begin
      v_pub := make_timestamptz(
        extract(year from v_day)::int,
        extract(month from v_day)::int,
        extract(day from v_day)::int,
        v_match[1]::int,
        v_match[2]::int,
        0,
        'Europe/Berlin'
      );
    exception when others then
      return false;
    end;

    return v_pub >= p_as_of - interval '24 hours'
       and v_pub <= p_as_of + interval '5 minutes';
  end if;

  if v.source_id=1 then
    if not coalesce(v.fresh_delivery_eligible,false) then return false; end if;
    if coalesce(v.raw->>'delivery_lane','') in ('fresh_global','fresh_borough') then
      return true;
    end if;
    if v.raw->>'delivery_lane' <> 'coverage_proven'
       or v.raw#>>'{_newness,method}' <> 'source_timestamp'
       or coalesce(v.raw#>>'{_newness,source_published_at}','')
          !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}' then
      return false;
    end if;
    begin
      v_pub := (v.raw#>>'{_newness,source_published_at}')::timestamptz;
    exception when others then
      return false;
    end;
    return v_pub >= p_as_of - interval '24 hours'
       and v_pub <= p_as_of + interval '5 minutes';
  end if;

  if not coalesce(v.fresh_delivery_eligible,false) then
    return false;
  end if;

  v_label := nullif(btrim(coalesce(v.enrichment_evidence#>>'{preview,facts,published_text}','')),'');
  if v_label is not null then
    if v_label ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then
      begin
        return to_date(v_label,'YYYY-MM-DD') = (p_as_of at time zone 'Europe/Berlin')::date;
      exception when others then
        return false;
      end;
    elsif v_label ~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{4}$' then
      begin
        return to_date(v_label,'DD.MM.YYYY') = (p_as_of at time zone 'Europe/Berlin')::date;
      exception when others then
        return false;
      end;
    elsif v_label ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}(:[0-9]{2}([.][0-9]+)?)?(Z|[+-][0-9]{2}:[0-9]{2})$' then
      begin
        v_pub := v_label::timestamptz;
        return v_pub >= p_as_of - interval '24 hours'
           and v_pub <= p_as_of + interval '5 minutes';
      exception when others then
        return false;
      end;
    end if;
  end if;

  return true;
end;
$function$

