CREATE OR REPLACE FUNCTION app_private.enqueue_partial_coop_provider_checks()
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  r record;
  v_request_id bigint;
  v_count integer := 0;
begin
  delete from app_private.coop_provider_index_requests
  where processed_at is not null and processed_at < now() - interval '24 hours';

  for r in
    select c.*
    from app_private.coop_provider_query_config() c
    join public.sources s on s.id=c.source_id
    where s.enabled=true and s.runtime_mode='live' and s.delivery_mode='live'
      and not exists (
