        where q.source_id=c.source_id and q.query_kind=c.query_kind
          and q.processed_at is null and q.requested_at > now()-interval '10 minutes'
      )
  loop
    select net.http_get(url := r.query_url, timeout_milliseconds := 15000) into v_request_id;
    insert into app_private.coop_provider_index_requests(source_id,query_kind,request_id)
    values(r.source_id,r.query_kind,v_request_id);
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
